mapper.select:
SELECT m.id, m.user_id AS userId, m.name, m.contact_name AS contactName, m.contact_phone AS contactPhone, m.address, m.business_hours AS businessHours, m.province, m.city, m.district, m.type_id AS typeId, m.status, m.longitude, m.latitude, ST_Distance_Sphere(POINT(m.longitude, m.latitude), POINT(#{lng}, #{lat})) AS distanceMeters FROM `merchant` m WHERE m.status = 1 AND m.location_status = 1 AND m.longitude IS NOT NULL AND m.latitude IS NOT NULL
AND m.type_id = #{typeId}
AND ST_Distance_Sphere(POINT(m.longitude, m.latitude), POINT(#{lng}, #{lat})) <= #{radiusMeters} ORDER BY distanceMeters ASC, m.id DESC LIMIT #{offset}, #{size}

SELECT COUNT(1) FROM `merchant` m WHERE m.status = 1 AND m.location_status = 1 AND m.longitude IS NOT NULL AND m.latitude IS NOT NULL
AND m.type_id = #{typeId}
AND ST_Distance_Sphere(POINT(m.longitude, m.latitude), POINT(#{lng}, #{lat})) <= #{radiusMeters}
